begin;
set local statement_timeout='90s';
update push_private.notice_jobs set next_at='infinity' where generation>delivered_generation;
do $$
declare coach uuid:=gen_random_uuid();pupil uuid:=gen_random_uuid();second_pupil uuid:=gen_random_uuid();other uuid:=gen_random_uuid();
 rel uuid:=gen_random_uuid();rel2 uuid:=gen_random_uuid();foreign_rel uuid:=gen_random_uuid();self_rel uuid:=gen_random_uuid();
 device uuid:=gen_random_uuid();binding uuid:=gen_random_uuid();m uuid:=gen_random_uuid();m2 uuid:=gen_random_uuid();m3 uuid:=gen_random_uuid();
 job jsonb;prefs jsonb;result jsonb;template uuid;exercise uuid;scheduled uuid:=gen_random_uuid();execution uuid;clip uuid;claim uuid:=gen_random_uuid();event uuid;
begin
 update push_private.settings set enabled=true,coach_enabled=true,firebase_project_id='entrenaop-dev';
 insert into auth.users(id,email) values(coach,coach||'@coach-push.invalid'),(pupil,pupil||'@coach-push.invalid'),(second_pupil,second_pupil||'@coach-push.invalid'),(other,other||'@coach-push.invalid');
 insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),coach,'totp','verified',now(),now()),(gen_random_uuid(),other,'totp','verified',now(),now());
 insert into public.trainer_access(trainer_id,enabled,client_limit,last_reason) values(coach,true,5,'Contrato push'),(other,true,5,'Aislamiento');
 insert into public.trainer_client_relations(id,trainer_id,client_id) values(rel,coach,pupil),(rel2,coach,second_pupil),(foreign_rel,other,pupil);
 perform set_config('request.jwt.claim.sub',coach::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 if (public.prepare_my_professional_push_delivery(coach)->>'personal_enabled')::boolean then raise exception 'Alta profesional activa avisos personales';end if;
 reset role;
 insert into push_private.installations(id,owner_id,secret_hash,binding_id,platform,token,token_hash)
 values(device,coach,encode(extensions.digest(repeat('c',64),'sha256'),'hex'),binding,'android',device::text,encode(sha256(convert_to(device::text,'UTF8')),'hex'));
 insert into push_private.preferences(owner_id,quiet_enabled) values(coach,false);
 insert into trainer_private.messages(id,relation_id,sender_id,body) values(gen_random_uuid(),rel,pupil,'Antes de consentir');
 if exists(select 1 from push_private.coach_events where owner_id=coach) then raise exception 'Activa por defecto';end if;
 perform set_config('request.jwt.claim.sub',coach::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 if (public.get_my_coach_push_preferences(coach)->>'enabled')::boolean then raise exception 'Consentimiento implícito';end if;
 begin perform public.get_my_coach_push_preferences(other);raise exception 'Cambia propietario';exception when insufficient_privilege then null;end;
 begin perform 1 from push_private.coach_events;raise exception 'Expone fuentes';exception when insufficient_privilege then null;end;
 prefs:=public.save_my_coach_push_preferences(coach,0,true,true,true);
 begin perform public.save_my_coach_push_preferences(coach,0,false,true,true);raise exception 'Sobrescribe revisión obsoleta';exception when serialization_failure then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal1')::text,true);
 begin perform public.save_my_coach_push_preferences(coach,1,false,true,true);raise exception 'Sin MFA';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 reset role;
 insert into trainer_private.messages(id,relation_id,sender_id,body) values(m,rel,pupil,'Texto reservado'),(m2,rel2,second_pupil,'Otro alumno');
 insert into trainer_private.messages(id,relation_id,sender_id,body) values(gen_random_uuid(),rel,coach,'Mensaje propio'),(gen_random_uuid(),foreign_rel,pupil,'Ajeno');
 if (select count(*) from push_private.notice_jobs where owner_id=coach and kind='coachMessage')<>1
  or (select generation from push_private.notice_jobs where owner_id=coach and kind='coachMessage')<>2 then raise exception 'No agrupa entre alumnos';end if;
 if (select next_at<clock_timestamp()+interval '50 seconds' from push_private.notice_jobs where owner_id=coach and kind='coachMessage') then raise exception 'Envía inmediatamente';end if;
 set local role authenticated;
 result:=public.resolve_my_coach_notice(coach,'coachMessage');
 if result->>'kind'<>'conversation' or result->>'target_id' not in (rel::text,rel2::text) or result::text like '%Texto reservado%' then raise exception 'Destino incorrecto o filtra contenido';end if;
 perform public.read_trainer_messages(coach,array[m,m2]);
 reset role;
 update push_private.notice_jobs set next_at=clock_timestamp()-interval '1 second' where owner_id=coach;
 set local role service_role;
 job:=public.claim_student_notice_jobs(1)->0;
 if job is null or public.prepare_student_notice_job((job->>'job_id')::uuid,(job->>'claim_id')::uuid,(job->>'generation')::bigint,binding) is not null then raise exception 'Envía mensajes leídos';end if;
 perform public.finish_student_notice_job((job->>'job_id')::uuid,(job->>'claim_id')::uuid,(job->>'generation')::bigint,binding,'skipped');
 reset role;
 insert into trainer_private.messages(id,relation_id,sender_id,body) values(m3,rel,pupil,'Nuevo');
 update push_private.notice_jobs set next_at=clock_timestamp()-interval '1 second' where owner_id=coach;
 set local role service_role;
 job:=public.claim_student_notice_jobs(1)->0;
 if public.prepare_student_notice_job((job->>'job_id')::uuid,(job->>'claim_id')::uuid,(job->>'generation')::bigint,gen_random_uuid()) is not null then raise exception 'Acepta asociación ajena';end if;
 if public.prepare_student_notice_job((job->>'job_id')::uuid,(job->>'claim_id')::uuid,(job->>'generation')::bigint,binding)->>'kind'<>'coachMessage' then raise exception 'No prepara mensajes';end if;
 reset role;
 insert into trainer_private.messages(id,relation_id,sender_id,body) values(gen_random_uuid(),rel2,second_pupil,'Llega durante envío');
 set local role service_role;
 perform public.finish_student_notice_job((job->>'job_id')::uuid,(job->>'claim_id')::uuid,(job->>'generation')::bigint,binding,'sent');
 reset role;
 if not exists(select 1 from push_private.notice_jobs where owner_id=coach and generation>delivered_generation and next_at>=last_sent_at+interval '10 minutes') then raise exception 'Pierde llegada o ignora pausa';end if;
 update push_private.coach_preferences set messages=false where owner_id=coach;
 if push_private.coach_event_pending((select id from push_private.coach_events where message_id=m3),coach) then raise exception 'Ignora preferencia';end if;
 update push_private.coach_preferences set messages=true where owner_id=coach;
 update public.trainer_access set enabled=false where trainer_id=coach;
 if push_private.coach_event_pending((select id from push_private.coach_events where message_id=m3),coach) then raise exception 'Envía sin acceso';end if;
 update public.trainer_access set enabled=true where trainer_id=coach;
 -- Vídeos: reservar/procesar NO genera un aviso; solo listo y compartido.
 set local role authenticated;
 exercise:=public.save_trainer_exercise(gen_random_uuid(),'{"name":"Técnica","description":"Contrato","muscle_groups":["espalda"],"equipment":["barra"],"difficulty":"intermedio","exercise_type":"repeticiones"}');
 template:=public.save_trainer_workout(gen_random_uuid(),jsonb_build_object('name','Técnica','blocks',jsonb_build_array(jsonb_build_object('name','Fuerza','format','straight_sets','rounds',1,'rest_after_seconds',0,'exercises',jsonb_build_array(jsonb_build_object('exercise_id',exercise,'sets',jsonb_build_array(jsonb_build_object('target_reps',8,'rest_after_seconds',60))))))));
 perform public.assign_trainer_workout(scheduled,rel,template,current_date,null);
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 execution:=public.start_scheduled_workout(scheduled);
 clip:=public.reserve_exercise_video_upload('client_technique',gen_random_uuid(),42,'fixture.b-cdn.net',1000000,scheduled,execution,null);
 reset role;
 if exists(select 1 from push_private.coach_events where asset_id=clip) then raise exception 'Avisa al reservar';end if;
 perform public.claim_exercise_video_creation(clip,claim);
 perform public.complete_exercise_video_creation(clip,claim,gen_random_uuid());
 update public.exercise_video_assets set shared=false where id=clip;
 update public.exercise_video_assets set status='ready',duration_seconds=90,playback_bytes=1000000,provider_storage_bytes=2000000 where id=clip;
 if exists(select 1 from push_private.coach_events where asset_id=clip) then raise exception 'Avisa sin compartir';end if;
 update public.exercise_video_assets set shared=true where id=clip;
 select id into event from push_private.coach_events where asset_id=clip;
 if event is null or not push_private.coach_event_pending(event,coach) then raise exception 'No avisa listo y compartido';end if;
 update public.exercise_video_assets set shared=false where id=clip;
 if push_private.coach_event_pending(event,coach) then raise exception 'Ignora retirada';end if;
 update public.exercise_video_assets set shared=true where id=clip;
 if (select count(*) from push_private.coach_events where asset_id=clip)<>1 then raise exception 'Duplica al volver a compartir';end if;
 perform set_config('request.jwt.claim.sub',coach::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 if public.resolve_my_coach_notice(coach,'coachVideo')->>'target_id'<>scheduled::text then raise exception 'No abre sesión propia';end if;
 begin perform public.read_my_coach_video(other,clip);raise exception 'Acuse ajeno';exception when insufficient_privilege then null;end;
 perform public.read_my_coach_video(coach,clip);perform public.read_my_coach_video(coach,clip);
 reset role;
 if push_private.coach_event_pending(event,coach) then raise exception 'Envía vídeo marcado visto';end if;
 update public.trainer_client_relations set ended_at=clock_timestamp(),ended_by=coach where id=rel;
 if push_private.coach_event_pending((select id from push_private.coach_events where message_id=m3),coach) then raise exception 'Envía tras terminar vínculo';end if;
 if has_function_privilege('anon','public.get_my_coach_push_preferences(uuid)','execute')
  or has_function_privilege('authenticated','push_private.coach_event_pending(uuid,uuid)','execute') then raise exception 'Permisos excesivos';end if;
 -- Conserva las reglas existentes y el descanso con cambios de hora.
 set local role authenticated;
 if not (public.set_my_device_personal_push_delivery(coach,device,repeat('c',64),true)->>'personal_enabled')::boolean then raise exception 'No activa canal personal';end if;
 result:=public.set_my_device_personal_push_delivery(coach,device,repeat('c',64),false);
 if (result->>'personal_enabled')::boolean or not (result->>'professional_enabled')::boolean then raise exception 'Desactivar personal apaga profesional';end if;
 reset role;
 if push_private.notice_due(coach,'coachVideo',now(),now(),now())<now()+interval '10 minutes' then raise exception 'Sin pausa vídeos';end if;
 update push_private.preferences set quiet_enabled=true,timezone='Europe/Madrid',quiet_start=1320,quiet_end=480 where owner_id=coach;
 if push_private.next_allowed(coach,'2026-10-24 21:30Z')<>'2026-10-25 07:00Z'::timestamptz then raise exception 'Descanso DST';end if;
end $$;
select 'coach_grouped_push: OK' as result;
rollback;
